import * as React from 'react';
// Vite `?raw`: the page renders the real CHANGELOG.md rather than a
// hand-kept copy, so the two can't drift. CHANGELOG.md stays the single
// source of truth — it's generated by standard-version from conventional
// commits, and nothing here should ever be edited by hand.
import changelogSource from '../../../CHANGELOG.md?raw';
import { getRoleColor, type RoleName } from '../../theme/roles';
import { parseChangelog } from './changelog-parse';

/** Section name -> role used for its accent. Unlisted sections fall back to neutral. */
const SECTION_TONE: Record<string, RoleName> = {
  Features: 'fg.success',
  'Bug Fixes': 'fg.critical',
  Performance: 'fg.info',
  Refactoring: 'fg.warning',
  Documentation: 'fg.neutral.subtle',
};

const monoStack = 'ui-monospace, SFMono-Regular, Menlo, monospace';

export const Changelog: React.FC<{ source?: string }> = ({ source = changelogSource }) => {
  const releases = React.useMemo(() => parseChangelog(source), [source]);

  const text = getRoleColor('fg.primary');
  const muted = getRoleColor('fg.neutral.subtle');
  const border = getRoleColor('border.default');
  const subtle = getRoleColor('bg.neutral.subtle');
  const link = getRoleColor('interactive.primary');

  if (!releases.length) {
    return <p style={{ color: muted }}>No released versions yet.</p>;
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 40 }}>
      {releases.map((release, i) => (
        <section key={release.version + i} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <header style={{ display: 'flex', alignItems: 'baseline', gap: 12, flexWrap: 'wrap', borderBottom: `1px solid ${border}`, paddingBottom: 8 }}>
            <h3 style={{ margin: 0, fontSize: 20, fontWeight: 700, color: text, letterSpacing: '-0.01em' }}>
              {release.compareUrl ? (
                <a href={release.compareUrl} target="_blank" rel="noreferrer" style={{ color: text, textDecoration: 'none' }}>
                  {release.version}
                </a>
              ) : (
                release.version
              )}
            </h3>
            {i === 0 && (
              <span
                style={{
                  fontSize: 11,
                  fontWeight: 600,
                  textTransform: 'uppercase',
                  letterSpacing: '0.04em',
                  color: getRoleColor('fg.on-interactive'),
                  backgroundColor: link,
                  borderRadius: 999,
                  padding: '2px 8px',
                }}
              >
                Latest
              </span>
            )}
            {release.date && (
              <time style={{ fontSize: 13, color: muted, fontVariantNumeric: 'tabular-nums' }}>{release.date}</time>
            )}
          </header>

          {release.sections
            .filter((s) => s.entries.length)
            .map((s) => (
              <div key={s.title} style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                <h4
                  style={{
                    margin: 0,
                    fontSize: 12,
                    fontWeight: 700,
                    textTransform: 'uppercase',
                    letterSpacing: '0.06em',
                    color: getRoleColor(SECTION_TONE[s.title] ?? 'fg.neutral.subtle'),
                  }}
                >
                  {s.title}
                </h4>
                <ul style={{ margin: 0, padding: 0, listStyle: 'none', display: 'flex', flexDirection: 'column', gap: 6 }}>
                  {s.entries.map((e, j) => (
                    <li key={j} style={{ display: 'flex', gap: 8, alignItems: 'baseline', flexWrap: 'wrap', fontSize: 14, lineHeight: 1.55, color: text }}>
                      {e.scope && (
                        <code
                          style={{
                            fontFamily: monoStack,
                            fontSize: 12,
                            backgroundColor: subtle,
                            border: `1px solid ${border}`,
                            borderRadius: 4,
                            padding: '1px 6px',
                            color: muted,
                            whiteSpace: 'nowrap',
                          }}
                        >
                          {e.scope}
                        </code>
                      )}
                      <span style={{ flex: '1 1 260px', minWidth: 0 }}>{e.text}</span>
                      {e.hash && e.url && (
                        <a
                          href={e.url}
                          target="_blank"
                          rel="noreferrer"
                          style={{ fontFamily: monoStack, fontSize: 12, color: link, textDecoration: 'none', whiteSpace: 'nowrap' }}
                        >
                          {e.hash}
                        </a>
                      )}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
        </section>
      ))}
    </div>
  );
};

export default Changelog;
